installer-gui-script.script:
function nvdecCheck() {
    if (!system.files.fileExistsAtPath('/Library/GPUBundles/NVMTLDriver.bundle/Contents/MacOS/NVMTLDriver')) {
        my.result.message = '没有找到 nullmoth 驱动的 NVMTLDriver.bundle，请先安装 NVRM 驱动（2.7.1 / 2.7.2 已实机验证）。';
        my.result.type = 'Fatal';
        return false;
    }
    if (!system.files.fileExistsAtPath('/Library/GPUBundles/nvmtl/nvrm610.conf')) {
        my.result.message = '没有找到 /Library/GPUBundles/nvmtl/nvrm610.conf，驱动版本可能不是 2.7.1 / 2.7.2。';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
